Node* parent = nullptr;

// If root is the child, there's no parent
if (root == child) {
    return nullptr;
}

// Use a stack or recursion for DFS
std::stack<Node*> stack;
stack.push(root);

while (!stack.empty()) {
    current = stack.top();
    stack.pop();

    // Check if current node has the child as its direct child
    // For internal nodes, we need to check all children pointers

    // If current is an internal node (non-leaf)
    if (!current->is_leaf) {
        for (int i = 0; i <= current->n; i++) {
            if (current->children[i] == child) {
                return current;
            }
            // Continue searching in children
            if (current->children[i] != nullptr) {
                stack.push(current->children[i]);
            }
        }
    }
}

return nullptr;

